	function serializeTable(c, e)
		if type(c) ~= "table" then
			return c
		end
		e = e or {}
		if e[c] then
			return nil
		end
		e[c] = true
		local f = {}
		for c, g in pairs(c) do
			if typeof(g) == "Color3" then
				f[c] = {
					["__type"] = "Color3",
					["r"] = math.round(g.R * 255),
					["g"] = math.round(g.G * 255),
					["b"] = math.round(g.B * 255),
				}
			elseif type(g) == "table" then
				local h = serializeTable(g, e)
				if h ~= nil then
					f[c] = h
				end
			elseif type(g) == "boolean" or type(g) == "number" or type(g) == "string" then
				f[c] = g
			end
		end
		return f
	end
	local function lb(c)
		if type(c) ~= "table" then
			return false
		end
		if c.__type == "Color3" then
			return true
		end
		if (c.r or c.R) and ((c.g or c.G) and (c.b or c.B)) then
			return true
		end
		if #c == 3 and (type(c[1]) == "number" and (type(c[2]) == "number" and type(c[3]) == "number")) then
			return true
		end
		return false
	end
	local function mb(c)
		local e = c.r or c.R or c[1]
		local f = c.g or c.G or c[2]
		local g = c.b or c.B or c[3]
		e = tonumber(e) or 255
		f = tonumber(f) or 255
		g = tonumber(g) or 255
		if e > 1 or f > 1 or g > 1 then
			return Color3.fromRGB(e, f, g)
		else
			return Color3.new(e, f, g)
		end
	end
	function deserializeTable(c, e)
		if type(c) ~= "table" or type(e) ~= "table" then
			return
		end
		for e, f in pairs(e) do
			if type(f) == "table" then
				if lb(f) then
					c[e] = mb(f)
				else
					if type(c[e]) ~= "table" then
						c[e] = {}
					end
					deserializeTable(c[e], f)
				end
			else
				c[e] = f
			end
		end
