		Db = RunService.Heartbeat:Connect(function()
			local e = os.clock()
			local f = e - c
			c = e
			if f > 0.1 then
				f = 0.0166
			end
			if not activeLoop then
				return
			end
			if not x.SpeedBoostEnabled then
				return
			end
			local g = localPlayer.Character
			if not g then
				return
			end
			local h = g:FindFirstChildOfClass("Humanoid")
			local i = g:FindFirstChild("HumanoidRootPart")
			if not h or not i or h.Health <= 0 then
				return
			end
			pcall(function()
				g:SetAttribute("BypassFlingAntiCheat", true)
				g:SetAttribute("ForensicsLaunch", true)
				g:SetAttribute("BypassNoclipAntiCheat", true)
				g:SetAttribute("donttrack", true)
				g:SetAttribute("AC_MovementGraceUntil", 999999999)
				g:SetAttribute("AC_AllowedSpeed", 999999)
				g:SetAttribute("NetTraversalUntil", 999999999)
			end)
			local j = localPlayer.Team
			local k = j and j.Name
			local l = x.ModifierTeamFilter or "Both"
			if l == "Survivors" and k == "Killer" then
				return
			end
			if l == "Killer" and k ~= "Killer" then
				return
			end
			if k == "Spectators" or k == "Spectator" then
				return
			end
			if
				g:GetAttribute("IsStunned") == true
				or g:GetAttribute("Immobile") == true
				or g:GetAttribute("IsHooked") == true
				or g:GetAttribute("Knocked") == true
				or g:GetAttribute("IsCarried") == true
			then
				return
			end
			local m = h.MoveDirection
			if m.Magnitude > 0.05 then
				local c = g:GetAttribute("Speed") or 16
				local e = tonumber(x.SpeedBoost) or 1.3
				if x.CountSpeedPerks then
					local c = g:GetAttribute("speedboost") or 1
					e = c + (e - 1)
				end
				local h = tick()
				local j = (k ~= "Killer")
				if j and (x.SimulateQuickRecovery and (h < (_G.VD_QuickRecoveryBoostEnd or 0))) then
					e = e + 0.4
				end
				if j and (x.SimulatePerfectLanding and (h < (_G.VD_PerfectLandingBoostEnd or 0))) then
					e = e + 0.4
				end
				local l = (Vector3.new(m.X, 0, m.Z)).Unit
				local n = i.AssemblyLinearVelocity
				local o = c * e
				local p = math.min(o, -611251 + 611269.5)
				i.AssemblyLinearVelocity = Vector3.new(l.X * p, n.Y, l.Z * p)
				local q = o - p
				if q > 0 then
					local c = l * (q * f)
					i.CFrame = i.CFrame + c
				end
			end
		end)
		registerConnection(Db)
	end
