	local function Eb(c)
		if not c or not c.Parent then
			return
		end
		local e = c.ClassName
		if e ~= "Model" and (e ~= "Part" and e ~= "Folder") then
			return
		end
		local f = c.Name
		if f == "Generator" and c:IsA("Model") then
			if not table.find(cachedGenerators, c) then
				table.insert(cachedGenerators, c)
			end
		elseif
			c:IsA("Model")
			and (c.Parent and c.Parent.Name == "Pallets" or c.Name == "Pallet" or c:FindFirstChild("Intact"))
		then
			if not table.find(cachedPallets, c) then
				table.insert(cachedPallets, c)
			end
		elseif f == "Window" or (f:lower()):find("window") or f == "Vault" or (f:lower()):find("vault") then
			local e = false
			local f = false
			local g = false
			for c, h in ipairs(c:GetDescendants()) do
				local i = h.Name:lower()
				if i == "bottom" then
					e = true
				elseif i == "inviswall" then
					f = true
				elseif i == "vaulttrigger" then
					g = true
				end
			end
			if e and (f and g) then
				if not table.find(cachedVaults, c) then
					table.insert(cachedVaults, c)
				end
			end
		elseif f == "VaultTrigger" or (f:lower()):find("vaulttrigger") then
			local e = c.Parent
			if e and (e:IsA("Model") or e:IsA("Folder")) then
				local c = false
				local f = false
				for e, g in ipairs(e:GetDescendants()) do
					local h = g.Name:lower()
					if h == "bottom" then
						c = true
					elseif h == "inviswall" then
						f = true
					end
				end
				if c and f then
					if not table.find(cachedVaults, e) then
						table.insert(cachedVaults, e)
					end
				end
			end
		elseif f == "BloodEffect" and c:IsA("BasePart") then
			if not table.find(cachedBloodEffects, c) then
				table.insert(cachedBloodEffects, c)
			end
		elseif f == "Hook" or f == "HookPoint" then
			local e = Players:GetPlayers()
			local f = {}
			for c, e in ipairs(e) do
				if e.Character then
					f[e.Character] = true
				end
			end
			local g = false
			local h = c
			while h and h ~= workspace do
				if f[h] then
					g = true
					break
				end
				h = h.Parent
			end
			if not g then
				local e = nil
				if c:IsA("BasePart") then
					e = c
