				end
				if e then
					if not table.find(cachedHooks, e) then
						table.insert(cachedHooks, e)
					end
				end
			end
		elseif
			(f == "ExitLever" or c:FindFirstChild("ExitLever", true) or c:FindFirstChild("ExitLever"))
			and not (
				(f:lower()):find("spot")
				or (f:lower()):find("spawn")
				or (f:lower()):find("marker")
				or (f:lower()):find("point")
			)
		then
			local e = (c.Name == "ExitLever" and c)
				or c:FindFirstChild("ExitLever", true)
				or c:FindFirstChild("ExitLever")
			if e and not table.find(cachedGates, e) then
				table.insert(cachedGates, e)
			end
		elseif f == "BearTrap" or (CollectionService and CollectionService:HasTag(c, "BearTrap")) then
			if not table.find(cachedBearTraps, c) then
				table.insert(cachedBearTraps, c)
			end
		elseif (c.Parent and c.Parent.Name == "Pumpkins") or ((f:lower()):find("pumpkin") and f ~= "Pumpkins") then
			if not c:IsA("Folder") then
				local e = (c:IsA("Model") and c) or (c:IsA("BasePart") and c)
				if e and not table.find(cachedPumpkins, e) then
					table.insert(cachedPumpkins, e)
				end
			end
		end
	end
