	function updateSCPCache()
		local c = {}
		local e = {}
		local function f(f)
			if f and not e[f] then
				e[f] = true
				table.insert(c, f)
			end
		end
		local g = workspace:FindFirstChild("Map")
		if g then
			for c, e in ipairs({
				"1",
				"2",
			}) do
				local h = g:FindFirstChild(e)
				if h then
					for c, e in ipairs(h:GetChildren()) do
						if e:IsA("Model") then
							f(e)
						end
					end
				end
			end
			local function c(c)
				return string.match(c:lower(), "^scp%d*$") ~= nil
			end
			for e, g in ipairs(g:GetChildren()) do
				if g.Name ~= "1" and g.Name ~= "2" then
					if g:IsA("Model") and c(g.Name) then
						f(g)
					elseif g:IsA("Folder") or g:IsA("Model") then
						for e, g in ipairs(g:GetChildren()) do
							if g:IsA("Model") and c(g.Name) then
								f(g)
							end
						end
					end
				end
			end
			for c, e in ipairs(g:GetChildren()) do
				if e:IsA("Model") and e ~= localPlayer.Character then
					local c = e:GetAttribute("Cured")
					if tonumber(c) == 3 then
						f(e)
					end
				end
			end
		end
		Ib = c
	end
	local Jb = nil
	local Kb = "Unknown Map"
	function getMapName()
		local c, e = pcall(function()
			return (game:GetService("Players")).LocalPlayer.PlayerGui.Darkness.Frame.MapInfo.MapTitle.Text
		end)
		if c and (e and e ~= "") then
			if e:upper() == "NOSTROMO" then
				return "Loading..."
			end
			return e
		end
		local f = workspace:FindFirstChild("Map")
		if not f then
			Jb = nil
			Kb = "Unknown Map"
			return Kb
		end
		local g = f:FindFirstChildOfClass("Model") or f:FindFirstChildOfClass("Folder") or f
		if g == Jb and Kb ~= "Unknown Map" then
			return Kb
		end
		Jb = g
		if f:FindFirstChild("HooksMeat", true) then
			Kb = "BLOODBATH! Club"
			return Kb
		end
		if f:FindFirstChild("Rooftop", true) then
			Kb = "Mercy Hospital Rooftop"
			return Kb
		end
		if f:FindFirstChild("inviswallasylum", true) then
			Kb = "Mount Massive Asylum"
			return Kb
		end
		if f:FindFirstChild("Tesla", true) then
			Kb = "Site 68"
			return Kb
		end
		if f:FindFirstChild("Breakwater", true) then
			Kb = "The Bay Harbor"
			return Kb
		end
		if f:FindFirstChild("RockVar0", true) then
			Kb = "Woodview Cabin"
			return Kb
		end
		local h = f:FindFirstChild("Model", true)
		if h then
			local c = (h:GetPivot()).Position
			if ((c - Vector3.new(-811.4, 212.8, -7774.5))).Magnitude < 100 then
				Kb = "Firelink Shrine"
				return Kb
			end
			if ((c - Vector3.new(1114.67, -16.92, -12.99))).Magnitude < 100 then
				Kb = "Valdelobos Village"
				return Kb
			end
		end
		Kb = "Unknown Map"
		return Kb
	end
	function applyBlockInteractions()
		pcall(function()
			local c = (game:GetService("ReplicatedStorage")):FindFirstChild("Remotes")
			c = c and c:FindFirstChild("Window")
			c = c and c:FindFirstChild("VaultEvent")
			if c then
				for e, f in ipairs(cachedVaults) do
					if f and f.Parent then
						for e, f in ipairs(f:GetDescendants()) do
							if f.Name == "VaultTrigger" then
								c:FireServer(f, true)
							end
						end
					end
				end
			end
		end)
		pcall(function()
			local c = (game:GetService("ReplicatedStorage")):FindFirstChild("Remotes")
			c = c and c:FindFirstChild("Pallet")
			c = c and c:FindFirstChild("PalletSlideEvent")
			if c then
				for e, f in ipairs(cachedPallets) do
					if f and f.Parent then
						for e, f in ipairs(f:GetDescendants()) do
							if f.Name == "PalletPointSlide" or f.Name:find("Slide") then
								c:FireServer(f, true)
							end
						end
					end
				end
			end
		end)
	end
	function releaseBlockInteractions()
		_G.VD_ReleasingBlockInteractions = true
		pcall(function()
			local c = (game:GetService("ReplicatedStorage")):FindFirstChild("Remotes")
			c = c and c:FindFirstChild("Window")
			c = c and c:FindFirstChild("VaultCompleteEvent")
			if c then
				local e = workspace:FindFirstChild("Map")
				local f = e or workspace
				for e, f in ipairs(f:GetDescendants()) do
					if f.Name == "VaultTrigger" then
						c:FireServer(f, false)
					end
				end
			end
		end)
		_G.VD_ReleasingBlockInteractions = false
		pcall(function()
			local c = (game:GetService("ReplicatedStorage")):FindFirstChild("Remotes")
			c = c and c:FindFirstChild("Pallet")
			c = c and c:FindFirstChild("PalletSlideCompleteEvent")
			if c then
