		end
		for e, f in ipairs(allEmotesList or {}) do
			if f.name == c or f.name:lower() == c:lower() then
				return f
			end
		end
		for e, f in ipairs(x.UserCustomEmotes or {}) do
			if f.name == c or f.name:lower() == c:lower() then
				return f
			end
		end
		return nil
	end
